uv run python - <<'EOF'
import json, os, glob, datetime
rows=[]
for p in glob.glob("logs/runs/P*.json"):
    try: d=json.load(open(p))
    except Exception: continue
    r=d.get("result") or {}
    t=os.path.getmtime(p)
    rows.append((t,d["case"],r.get("score"),r.get("deal"),d["session"]))
rows.sort()
for t,c,s,deal,sess in rows:
    ts=datetime.datetime.fromtimestamp(t)
    if ts>datetime.datetime(2026,10,11,0,0):
        print(ts.strftime("%m-%d %H:%M"),c,round(s,3) if s is not None else None,deal,sess)
EOF

