        else:
            t=mv.get("terms") or {}
            print("  S r%d %s"%(m["round"], mv.get("status")), {k:v for k,v in t.items() if k in("unit_price","payment_days","lead_time_days","contract_months","volume_per_year","ppm_commitment","chargeback_eur_per_complaint")}, "alts",len(mv.get("alternatives") or []), [cr.get("result") for cr in mv.get("claim_results") or []])
EOF

