uv run python - <<'EOF'
import json,glob,os
rows=[]
for f in sorted(glob.glob("logs/sessions/practice/P05_*.json"), key=os.path.getmtime):
    d=json.load(open(f)); r=d["result"]
    tr=r["trace"]
    to={}
    for m in tr:
        if m["actor"]=="buyer" and m["move"].get("type")=="timeout":
            to[m["move"].get("supplier_id") or m.get("supplier") or "?"]=to.get(m["move"].get("supplier_id") or "?",0)+1
    ends={}
    for sup,th in (d.get("threads") or {}).items():
        ends[sup[-6:]]=(th.get("status"), th.get("closed"))
    print(os.path.basename(f), round(r["score"] or 0,3), r.get("supplier_id"), (r.get("terms") or {}).get("unit_price"), "timeouts", sum(1 for m in tr if m["actor"]=="buyer" and m["move"].get("type")=="timeout"), "rounds", d["rounds"], ends)
EOF

